import json
from tau2.domains.retail.data_model import RetailDB
from tau2.domains.retail.tools import RetailTools

db = RetailDB.load()
tools = RetailTools(db)

results = {}

# Step 1: Authenticate
try:
    user_id = tools.find_user_id_by_email('maya.chen@email.com')
    results['user_id'] = user_id
    results['auth'] = 'success'
except ValueError as e:
    results['auth'] = 'email_failed'
    results['error'] = str(e)
    # Try listing all users
    all_users = {}
    for uid, u in db.users.items():
        all_users[uid] = {'email': u.email, 'name': u.name.first_name + ' ' + u.name.last_name}
    results['all_users'] = all_users

# Step 2: If auth succeeded, get user details and orders
if results.get('auth') == 'success':
    user = tools.get_user_details(results['user_id'])
    user_data = json.loads(user.model_dump_json())
    results['user'] = user_data

    results['orders'] = {}
    for oid in user_data.get('orders', []):
        try:
            order = tools.get_order_details(oid)
            results['orders'][oid] = json.loads(order.model_dump_json())
        except Exception as ex:
            results['orders'][oid] = {'error': str(ex)}

with open('/workspace/auth_results.json', 'w') as f:
